WITH lines AS (SELECT base.id, base.customer_id, base.coupon_codes, entry.product_id, entry.qty, entry.price, entry.promo FROM carts base LATERAL VIEW EXPLODE(base.items) x AS entry) SELECT id, customer_id, coupon_codes, price, promo, ROUND(price / SUM(price) OVER (PARTITION BY customer_id), 4) AS price_share, SUM(product_id) OVER (PARTITION BY customer_id) AS customer_id_sum_product_id, DENSE_RANK() OVER (ORDER BY price DESC NULLS FIRST) AS price_dense_rank, CUME_DIST() OVER (ORDER BY product_id NULLS LAST) AS product_id_cume_dist, MAX(qty) OVER (PARTITION BY customer_id) AS customer_id_max_qty FROM lines WHERE customer_id = 36
